```st
FUNCTION_BLOCK FB
VAR_INPUT
    runRequest      : BOOL;
    pressure        : REAL;
    pressureValid   : BOOL;
    fuelFlow        : REAL;
    steamFlow       : REAL;
    outletCmd       : INT;
    outletFeedback  : INT;
    resetBtn        : BOOL;
END_VAR
VAR_OUTPUT
    tripLatched     : BOOL;
    fuelPermit      : BOOL;
    currentCauseMask    : WORD;
    latchedCauseMask    : WORD;
    diagnosticActive   : BOOL;
END_VAR
VAR
    prev_resetBtn       : BOOL := FALSE;
    prev_runRequest     : BOOL := FALSE;
    prev_pressureValid  : BOOL := FALSE;
    prev_pressure       : REAL := 0.0;
    prev_fuelFlow       : REAL := 0.0;
    prev_steamFlow      : REAL := 0.0;
    prev_outletCmd      : INT := 0;
    prev_outletFeedback : INT := 0;
    prev_tripLatched    : BOOL := FALSE;
    prev_tripCondition  : BOOL := FALSE;
    prev_stickingCondition  : BOOL := FALSE;
    prev_prev_stickingCondition : BOOL := FALSE;
END_VAR

    // Trip condition
    tripCondition := runRequest AND (NOT pressureValid OR pressure >= 4500.0);

    // Reset edge detection
    resetRising := resetBtn AND NOT prev_resetBtn;

    // Trip latch logic
    IF resetRising AND prev_tripLatched AND NOT runRequest AND pressureValid AND pressure <= 4200.0 THEN
        tripLatched := FALSE;
        latchedCauseMask := 0;
    ELSIF prev_tripLatched THEN
        tripLatched := TRUE;
    ELSIF tripCondition THEN
        tripLatched := TRUE;
    ELSE
        tripLatched := FALSE;
    END_IF;

    // Current cause mask
    currentCauseMask := 0;

    IF runRequest THEN
        IF NOT pressureValid THEN
            currentCauseMask := 1;
        ELSIF pressure >= 4500.0 THEN
            // Valve sticking: requires this AND prev AND prev_prev all true
            stickingCondition := (outletCmd >= 50 AND outletFeedback <= 10);
            IF stickingCondition AND prev_stickingCondition AND prev_prev_stickingCondition THEN
                currentCauseMask := currentCauseMask OR 2;
            END_IF;
            // Combustion excess
            IF (fuelFlow >= 4.0 AND steamFlow <= 10.0) THEN
                currentCauseMask := currentCauseMask OR 4;
            END_IF;
            // Unlocated
            IF (currentCauseMask AND 6) = 0 THEN
                currentCauseMask := currentCauseMask OR 8;
            END_IF;
        END_IF;
    END_IF;

    // Outputs
    fuelPermit := runRequest AND NOT tripLatched;
    diagnosticActive := (currentCauseMask <> 0);

    IF tripLatched THEN
        latchedCauseMask := latchedCauseMask OR currentCauseMask;
    ELSE
        latchedCauseMask := 0;
    END_IF;

    // Update history
    prev_resetBtn := resetBtn;
    prev_runRequest := runRequest;
    prev_pressureValid := pressureValid;
    prev_pressure := pressure;
    prev_fuelFlow := fuelFlow;
    prev_steamFlow := steamFlow;
    prev_outletCmd := outletCmd;
    prev_outletFeedback := outletFeedback;
    prev_tripLatched := tripLatched;
    prev_tripCondition := tripCondition;
    prev_prev_stickingCondition := prev_stickingCondition;
    prev_stickingCondition := (outletCmd >= 50 AND outletFeedback <= 10);

END_FUNCTION_BLOCK
```

